-- Раньше icon хранил имя иконки Lucide для фронтенда (i-lucide-xxx).
-- Теперь это произвольная разметка <svg>...</svg> — можно вставить любую
-- SVG-иконку прямо в БД, фронтенд рендерит её как есть (см. SvgIcon.vue).
ALTER TABLE categories ALTER COLUMN icon TYPE TEXT;
ALTER TABLE categories ALTER COLUMN icon DROP DEFAULT;

